import{_t as e,it as t,n,rt as r}from"./chunks/framework.D2cFUyj2.js";var i=JSON.parse(`{"title":"Favoritos","description":"","frontmatter":{},"headers":[{"level":2,"title":"1. Añadir elementos a Favoritos","slug":"_1-anadir-elementos-a-favoritos","link":"#_1-anadir-elementos-a-favoritos","children":[]},{"level":2,"title":"2. Gestión de la lista y ordenación por arrastre","slug":"_2-gestion-de-la-lista-y-ordenacion-por-arrastre","link":"#_2-gestion-de-la-lista-y-ordenacion-por-arrastre","children":[]},{"level":2,"title":"3. Aparición en búsquedas y aspectos visuales","slug":"_3-aparicion-en-busquedas-y-aspectos-visuales","link":"#_3-aparicion-en-busquedas-y-aspectos-visuales","children":[]}],"relativePath":"es-ES/user-guide/settings/favorites.md","filePath":"es-ES/user-guide/settings/favorites.md","lastUpdated":1791112464000}`),a={name:`es-ES/user-guide/settings/favorites.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="favoritos" tabindex="-1">Favoritos <a class="header-anchor" href="#favoritos" aria-label="Permalink to “Favoritos”">​</a></h1><p>Favoritos te permite fijar carpetas, archivos, scripts o URLs web de uso frecuente con nombres personalizados y la máxima prioridad de búsqueda. La página se encuentra en <strong>Configuración → Favoritos</strong>.</p><h2 id="_1-anadir-elementos-a-favoritos" tabindex="-1">1. Añadir elementos a Favoritos <a class="header-anchor" href="#_1-anadir-elementos-a-favoritos" aria-label="Permalink to “1. Añadir elementos a Favoritos”">​</a></h2><p>En el formulario superior:</p><ul><li><strong>Nombre para mostrar</strong>: Alias personalizado opcional. Si se deja en blanco y el destino es local, Lertaro utiliza automáticamente el nombre del archivo o carpeta.</li><li><strong>Ruta de destino</strong>: Admite rutas absolutas locales, variables de entorno como <code>%USERPROFILE%</code>, rutas virtuales de Windows Shell como <code>shell:Downloads</code> o URLs completas que comiencen por <code>http://</code> / <code>https://</code>.</li><li><strong>Examinar</strong>: Pulsa <strong>Examinar carpeta</strong> o <strong>Examinar archivo</strong> para abrir el selector nativo de Windows.</li><li><strong>Añadir</strong>: Pulsa <strong>Añadir</strong> una vez introducida una ruta válida para guardarla.</li></ul><h2 id="_2-gestion-de-la-lista-y-ordenacion-por-arrastre" tabindex="-1">2. Gestión de la lista y ordenación por arrastre <a class="header-anchor" href="#_2-gestion-de-la-lista-y-ordenacion-por-arrastre" aria-label="Permalink to “2. Gestión de la lista y ordenación por arrastre”">​</a></h2><p>La lista inferior muestra todos los favoritos guardados con opciones de gestión:</p><ul><li><strong>Control de arrastre de seis puntos</strong>: Cada fila dispone de un tirador de seis puntos a la izquierda para reordenar elementos arrastrándolos. También puedes usar los botones <strong>Mover arriba</strong> / <strong>Mover abajo</strong>. El orden aquí define su posición en los resultados de búsqueda y en el menú de Navegación rápida.</li><li><strong>Edición en línea</strong>: Al pulsar editar, la fila se convierte directamente en un editor; puedes guardar o cancelar desde la propia fila sin reutilizar el formulario superior.</li><li><strong>Eliminar elemento</strong>: Elimina la entrada de Favoritos de forma segura.</li><li><strong>Vaciar lista</strong>: Cuando la lista no está vacía, el botón situado junto al título elimina todos los favoritos de una vez; permanece oculto cuando la lista está vacía.</li></ul><p>También puedes añadir directamente a Favoritos un único archivo o carpeta existente desde el menú de acciones del resultado de búsqueda. Lertaro muestra un diálogo para introducir el nombre visible y oculta esta acción si la misma ruta ya está en Favoritos.</p><h2 id="_3-aparicion-en-busquedas-y-aspectos-visuales" tabindex="-1">3. Aparición en búsquedas y aspectos visuales <a class="header-anchor" href="#_3-aparicion-en-busquedas-y-aspectos-visuales" aria-label="Permalink to “3. Aparición en búsquedas y aspectos visuales”">​</a></h2><ul><li><strong>Distintivo de estrella (★)</strong>: Los elementos favoritos coincidentes muestran un icono <strong>★</strong> destacado junto a su ruta en los resultados.</li><li><strong>Búsqueda por alias personalizado</strong>: Asigna nombres fáciles de recordar a rutas complejas (p. ej., nombrar <code>D:\\Workspace\\2026\\Q1\\Financial\\Summary.xlsx</code> como <code>Finanzas Q1</code>). Al buscar el alias, el archivo se recupera.</li><li><strong>Sincronización multidispositivo</strong>: Los favoritos se sincronizan automáticamente con el menú de <a href="./../hotkeys.html#_3-navegacion-rapida-activadores-de-raton"><strong>Navegación rápida</strong></a> y la pestaña Favoritos del <a href="./quick-panel.html#_4-pestanas-de-plugins-plugin-tabs"><strong>Panel rápido</strong></a>.</li></ul>`,11)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};